document.addEventListener('submit',async e=>{const f=e.target,u=f.getAttribute('hx-post');if(!u)return;e.preventDefault();const t=document.querySelector(f.getAttribute('hx-target'));if(t)t.textContent='Сохраняется…';try{const r=await fetch(u,{method:'POST',body:new FormData(f),credentials:'same-origin'}),h=await r.text();if(t)t.innerHTML=h;f.closest('.review-card')?.classList.toggle('excluded',!f.elements.included.checked)}catch(_){if(t)t.textContent='Ошибка сохранения'}});
